orUpdatedConfig, RefreshConfig); WhenItsTimeTo(TimedAction.ScanGrid, () => { var allTerminalBlocks = new List<IMyTerminalBlock>(); GridTerminalSystem.GetBlocks(allTerminalBlocks); var blocks = ExtractLocalTerminalBlocks(allTerminalBlocks); var foreignBlocks = ExtractForeignTerminalBlocks(allTerminalBlocks); _blocksProducingPower = ExtractPowerBlocks(blocks); _foreignBlocksProducingPower = ExtractPowerBlocks(foreignBlocks); _blocksWithStorage = ExtractStorageBlocks(blocks); _blocksProducingItems = ExtractItemProductionBlocks(blocks); _blocksHoldingGas = ExtractGasTanksBlocks(blocks); _doors = ExtractDoorBlocks(blocks); _blockWithTextSurfaces = ExtractTextSurfaceBlocks(blocks); }); WhenItsTimeTo(TimedAction.MonitorGrid, () => { _monitoring.UpdateData( _blocksProducingPower, _foreignBlocksProducingPower, _blocksWithStorage, _blocksProducingItems, _blocksHoldingGas); if (_autoProduceActive) _autoProducer.Produce( _monitoring.MonitoringData.GetItems(), _monitoring.MonitoringData.GetItemsInProduction(), _itemsToProduce, _blocksProducingItems); }); WhenItsTimeTo(TimedAction.CleanupStorage, () => { if (_autoCleanupStorages) _autoCleanup.Cleanup( _blocksWithStorage, _blocksProducingItems); }); WhenItsTimeTo(TimedAction.DisplayStats, () => _displayManager.Display(_monitoring.MonitoringData, _itemsToProduce, _blockWithTextSurfaces)); WhenItsTimeTo(TimedAction.ShutDownDoors, () => { if (_autoShutDownDoors) _doorManager.ShutDownDoorWhenOpenedLongerThanExpected(_doors); }); WhenItsTimeTo(TimedAction.ManageAirlocks, () => _doorManager.ManageAirLocks(_doors)); _logger.ShowLogs(); _alreadyRunning = false; } private static int GetActionFrequencyInMs(TimedAction action) { switch (action) { case TimedAction.ScanGrid: return 10000; case TimedAction.MonitorGrid: return 5000; case TimedAction.CleanupStorage: return 10000; case TimedAction.ManageAirlocks: return 1000; case TimedAction.ShutDownDoors: return 1000; case TimedAction.CheckForUpdatedConfig: return 10000; case TimedAction.DisplayStats: return 250; default: throw new Exception($"{nameof(action)} not out of range"); } } private void RefreshConfig() { var autoProduceActive = SetupCustomData(Settings.AUTO_PRODUCE_ITEMS_ACTIVE, "false"); var autoShutDownDoors = SetupCustomData(Settings.AUTO_SHUTDOWN_DOORS_ACTIVE, "false"); var autoCleanupStorages = SetupCustomData(Settings.AUTO_CLEANUP_STORAGES_ACTIVE, "false"); _autoProduceActive = InitConfig(autoProduceActive); _autoShutDownDoors = InitConfig(autoShutDownDoors); _autoCleanupStorages = InitConfig(autoCleanupStorages); var bulletproofGlassKeyName = $"{Settings.COMPONENT_THRESHOLD}-BulletproofGlass"; var canvasKeyName = $"{Settings.COMPONENT_THRESHOLD}-Canvas"; var computerKeyName = $"{Settings.COMPONENT_THRESHOLD}-ComputerComponent"; var constructionKeyName = $"{Settings.COMPONENT_THRESHOLD}-ConstructionComponent"; var detectorKeyName = $"{Settings.COMPONENT_THRESHOLD}-DetectorComponent"; var displayKeyName = $"{Settings.COMPONENT_THRESHOLD}-Display"; var explosivesKeyName = $"{Settings.COMPONENT_THRESHOLD}-ExplosivesComponent"; var girderKeyName = $"{Settings.COMPONENT_THRESHOLD}-GirderComponent"; var gravityGeneratorKeyName = $"{Settings.COMPONENT_THRESHOLD}-GeneratorComponent"; var interiorPlateKeyName = $"{Settings.COMPONENT_THRESHOLD}-InteriorPlate"; var largeTubeKeyName = $"{Settings.COMPONENT_THRESHOLD}-LargeTube"; var medicalKeyName = $"{Settings.COMPONENT_THRESHOLD}-MedicalComponent"; var metalGridKeyName = $"{Settings.COMPONENT_THRESHOLD}-MetalGrid"; var motorKeyName = $"{Settings.COMPONENT_THRESHOLD}-MotorComponent"; var powerCellKeyName = $"{Settings.COMPONENT_THRESHOLD}-PowerCell"; var radioCommunicationKeyName = $"{Settings.COMPONENT_THRESHOLD}-RadioCommunicationComponent"; var reactorKeyName = $"{Settings.COMPONENT_THRESHOLD}-ReactorComponent"; var smallTubeKeyName = $"{Settings.COMPONENT_THRESHOLD}-SmallTube"; var solarCellKeyName = $"{Settings.COMPONENT_THRESHOLD}-SolarCell"; var steelPlateKeyName = $"{Settings.COMPONENT_THRESHOLD}-SteelPlate"; var superconductorKeyName = $"{Settings.COMPONENT_THRESHOLD}-Superconductor"; var thrustKeyName = $"{Settings.COMPONENT_THRESHOLD}-ThrustComponent"; var gatlingAmmoBoxName = $"{Settings.COMPONENT_THRESHOLD}-GatlingAmmoBox"; var assaultCannonShellName = $"{Settings.COMPONENT_THRESHOLD}-AssaultCannonShell"; var largeRailgunSabotName = $"{Settings.COMPONENT_THRESHOLD}-LargeRailgunSabot"; var bulletproofGlassValue = SetupCustomData(bulletproofGlassKeyName, "0"); var canvasValue = SetupCustomData(canvasKeyName, "0"); var computerComponentValue = SetupCustomData(computerKeyName, "0"); var constructionComponentValue = SetupCustomData(constructionKeyName, "0"); var detectorComponentValue = SetupCustomData(detectorKeyName, "0"); var displayValue = SetupCustomData(displayKeyName, "0"); var explosivesComponentValue = SetupCustomData(explosivesKeyName, "0"); var girderComponentValue = SetupCustomData(girderKeyName, "0"); var gravityGeneratorComponentValue = SetupCustomData(gravityGeneratorKeyName, "0"); var interiorPlateValue = SetupCustomData(interiorPlateKeyName, "0"); var largeTubeValue = SetupCustomData(largeTubeKeyName, "0"); var medicalComponentValue = SetupCustomData(medicalKeyName, "0"); var metalGridValue = SetupCustomData(metalGridKeyName, "0"); var motorComponentValue = SetupCustomData(motorKeyName, "0"); var powerCellValue = SetupCustomData(powerCellKeyName, "0"); var radioCommunicationComponentValue = SetupCustomData(radioCommunicationKeyName, "0"); var reactorComponentValue = SetupCustomData(reactorKeyName, "0"); var smallTubeValue = SetupCustomData(smallTubeKeyName, "0"); var solarCellValue = SetupCustomData(solarCellKeyName, "0"); var steelPlateValue = SetupCustomData(steelPlateKeyName, "0"); var superconductorValue = SetupCustomData(superconductorKeyName, "0"); var thrustComponentValue = SetupCustomData(thrustKeyName, "0"); var gatlingAmmoBoxValue = SetupCustomData(gatlingAmmoBoxName, "0"); var assaultCannonShellValue = SetupCustomData(assaultCannonShellName, "0"); var largeRailgunSabotValue = SetupCustomData(largeRailgunSabotName, "0"); _itemsToProduce = new List<Item> { InitAutoProductionValue(bulletproofGlassValue, "BulletproofGlass"), InitAutoProductionValue(canvasValue, "Canvas"), InitAutoProductionValue(computerComponentValue, "ComputerComponent"), InitAutoProductionValue(constructionComponentValue, "ConstructionComponent"), InitAutoProductionValue(detectorComponentValue, "DetectorComponent"), InitAutoProductionValue(displayValue, "Display"), InitAutoProductionValue(explosivesComponentValue, "ExplosivesComponent"), InitAutoProductionValue(girderComponentValue, "GirderComponent"), InitAutoProductionValue(gravityGeneratorComponentValue, "GravityGeneratorComponent"), InitAutoProductionValue(interiorPlateValue, "InteriorPlate"), InitAutoProductionValue(largeTubeValue, "LargeTube"), InitAutoProductionValue(medicalComponentValue, "MedicalComponent"), InitAutoProductionValue(metalGridValue, "MetalGrid"), InitAutoProductionValue(motorComponentValue, "MotorComponent"), InitAutoProductionValue(powerCellValue, "PowerCell"), InitAutoProductionValue(radioCommunicationComponentValue, "RadioCommunicationComponent"), InitAutoProductionValue(reactorComponentValue, "ReactorComponent"), InitAutoProductionValue(smallTubeValue, "SmallTube"), InitAutoProductionValue(solarCellValue, "SolarCell"), InitAutoProductionValue(steelPlateValue, "SteelPlate"), InitAutoProductionValue(superconductorValue, "Superconductor"), InitAutoProductionValue(thrustComponentValue, "ThrustComponent"), InitAutoProductionValue(gatlingAmmoBoxValue, "NATO_25x184mmMagazine"), InitAutoProductionValue(assaultCannonShellValue, "MediumCalibreAmmo"), InitAutoProductionValue(largeRailgunSabotValue, "LargeRailgunAmmo") }; } private static Item InitAutoProductionValue(string rawThresholdAmount, string itemType) { int amount; MyDefinitionId itemDefinitionId; var isItemDefinitionValid = MyDefinitionId.TryParse($"MyObjectBuilder_BlueprintDefinition/{itemType}", out itemDefinitionId); var isAmountValid = int.TryParse(rawThresholdAmount, out amount); if (!isItemDefinitionValid) throw new Exception($"{itemType} is not a valid Item Type."); if (!isAmountValid) throw new Exception($"{rawThresholdAmount} is not a valid number for auto producing {itemType}."); return new Item(itemDefinitionId, amount); } private string SetupCustomData(string key, string defaultValue) { var actualValue = _configuration.GetConfig(key); if (actualValue == null) _configuration.SetConfig(key, defaultValue); return actualValue; } private static bool InitConfig(string customDataValue) => (customDataValue ?? string.Empty).Equals("true", StringComparison.InvariantCultureIgnoreCase); private List<BlockEntity<IMyTerminalBlock>> ExtractForeignTerminalBlocks(IEnumerable<IMyTerminalBlock> blocks) => blocks .Where(block => block.IsSameConstructAs(Me) == false) .Select(block => new BlockEntity<IMyTerminalBlock>(_logger, GridTerminalSystem, block)) .ToList(); private List<BlockEntity<IMyTerminalBlock>> ExtractLocalTerminalBlocks(IEnumerable<IMyTerminalBlock> blocks) => blocks .Where(block => block.IsSameConstructAs(Me)) .Select(block => new BlockEntity<IMyTerminalBlock>(_logger, GridTerminalSystem, block)) .ToList(); private static List<BlockEntity<IMyGasTank>> ExtractGasTanksBlocks(IEnumerable<BlockEntity<IMyTerminalBlock>> blocks) => blocks .Where(block => block.IsOfType<IMyGasTank>()) .Select(block => block.CastTo<IMyGasTank>()) .ToList(); private static List<BlockEntity<IMyDoor>> ExtractDoorBlocks(IEnumerable<BlockEntity<IMyTerminalBlock>> blocks) => blocks .Where(block => block.IsOfType<IMyDoor>()) .Where(block => block.Block .BlockDefinition .TypeIdString .IndexOf("hangar", StringComparison.InvariantCultureIgnoreCase) < 0) .Select(block => block.CastTo<IMyDoor>()) .ToList(); private static List<BlockEntity<IMyProductionBlock>> ExtractItemProductionBlocks(IEnumerable<BlockEntity<IMyTerminalBlock>> blocks) => blocks .Where(block => block.IsOfType<IMyProductionBlock>()) .Where(block => block.Block.HasInventory) .Select(block => block.CastTo<IMyProductionBlock>()) .ToList(); private static List<BlockEntity<IMyTerminalBlock>> ExtractStorageBlocks(IEnumerable<BlockEntity<IMyTerminalBlock>> blocks) => blocks .Where(block => block.Block.HasInventory) .ToList(); private static List<BlockEntity<IMyPowerProducer>> ExtractPowerBlocks(IEnumerable<BlockEntity<IMyTerminalBlock>> blocks) => blocks .Where(block => block.IsOfType<IMyPowerProducer>()) .Select(block => block.CastTo<IMyPowerProducer>()) .ToList(); private static List<BlockEntity<IMyTerminalBlock>> ExtractTextSurfaceBlocks(IEnumerable<BlockEntity<IMyTerminalBlock>> blocks) => blocks .Where(block => block.IsOfType<IMyTextSurfaceProvider>()) .ToList(); private void WhenItsTimeTo(TimedAction actionKey, Action action) { var totalMillisecond = GetActionFrequencyInMs(actionKey); if (_timerDictionary.ContainsKey(actionKey) == false) _timerDictionary.Add(actionKey, DateTime.MinValue); if (DateTime.Now.Subtract(_timerDictionary[actionKey]).TotalMilliseconds < totalMillisecond) return; var begin = DateTime.Now; action(); var end = DateTime.Now; var elapsed = end.Subtract(begin).Milliseconds; if (elapsed > 10) _logger.LogDebug($"{actionKey.ToString()} took {elapsed} ms to complete"); _timerDictionary[actionKey] = DateTime.Now; } private enum TimedAction { ScanGrid = 0, CleanupStorage = 1, ManageAirlocks = 2, ShutDownDoors = 3, CheckForUpdatedConfig = 5, DisplayStats = 6, MonitorGrid } 
 public class AutoCleanup { private readonly IMyGridAssistantLogger _logger; public AutoCleanup(IMyGridAssistantLogger logger) { _logger = logger; } public void Cleanup( IEnumerable<BlockEntity<IMyTerminalBlock>> storageBlocks, IEnumerable<BlockEntity<IMyProductionBlock>> producingItemBlocks) { var blocksWithStorage = storageBlocks .Where(x => x.Exists()) .Select(x => x.Block) .ToList(); var blocksProducingItems = producingItemBlocks .Where(x => x.Exists()) .Select(x => x.Block) .ToList(); MoveItemsInProperContainer(blocksWithStorage, blocksProducingItems); StackItems(blocksWithStorage, blocksProducingItems); } private static void MoveItemsInProperContainer( IReadOnlyCollection<IMyTerminalBlock> storageBlocks, IReadOnlyCollection<IMyProductionBlock> producingItemBlocks) { MoveComponentsToCargo(storageBlocks, producingItemBlocks); MoveIngotsToCargo(storageBlocks, producingItemBlocks); MoveToolsToCargo(storageBlocks, producingItemBlocks); MoveAmmoToCargo(storageBlocks, producingItemBlocks); MoveOresToCargo(storageBlocks, producingItemBlocks); } private static void MoveAmmoToCargo( IReadOnlyCollection<IMyTerminalBlock> storageBlocks, IEnumerable<IMyProductionBlock> producingItemBlocks) { var cargos = storageBlocks .Where(IsAmmoStorage) .ToList(); if (!cargos.Any()) return; var productionBlockInventories = producingItemBlocks .Where(x => !IsAmmoStorage(x)) .Where(IsNotDisassembling) .Select(b => b.OutputInventory); var storageBlockInventories = storageBlocks .Where(x => !IsAmmoStorage(x)) .Where(block => !(block is IMyLargeTurretBase)) .Select(b => b.GetInventory()); var inventories = productionBlockInventories .Concat(storageBlockInventories) .ToList(); inventories.ForEach(inventory => { var items = new List<MyInventoryItem>(); inventory.GetItems(items); items .Where(item => item.Type.GetItemInfo().IsAmmo) .ToList() .ForEach(item => { foreach (var cargo in cargos) if (TryTransferTo(inventory, cargo, item)) break; }); }); } private static void MoveToolsToCargo( IReadOnlyCollection<IMyTerminalBlock> storageBlocks, IEnumerable<IMyProductionBlock> producingItemBlocks) { var cargos = storageBlocks .Where(IsToolStorage) .ToList(); if (!cargos.Any()) return; var productionBlockInventories = producingItemBlocks .Where(x => !IsToolStorage(x)) .Where(IsNotDisassembling) .Select(b => b.OutputInventory); var storageBlockInventories = storageBlocks .Where(x => !IsToolStorage(x)) .Select(b => b.GetInventory()); var inventories = productionBlockInventories .Concat(storageBlockInventories) .ToList(); inventories.ForEach(inventory => { var items = new List<MyInventoryItem>(); inventory.GetItems(items); items .Where(item => item.Type.GetItemInfo().IsTool) .ToList() .ForEach(item => { foreach (var cargo in cargos) if (TryTransferTo(inventory, cargo, item)) break; }); }); } private static void MoveComponentsToCargo( IReadOnlyCollection<IMyTerminalBlock> storageBlocks, IEnumerable<IMyProductionBlock> producingItemBlocks) { var cargos = storageBlocks .Where(IsComponentStorage) .ToList(); if (!cargos.Any()) return; var productionBlockInventories = producingItemBlocks .Where(x => !IsComponentStorage(x)) .Where(IsNotDisassembling) .Select(b => b.OutputInventory); var storageBlockInventories = storageBlocks .Where(x => !IsComponentStorage(x)) .Select(b => b.GetInventory()); var inventories = productionBlockInventories .Concat(storageBlockInventories) .ToList(); inventories.ForEach(inventory => { var items = new List<MyInventoryItem>(); inventory.GetItems(items); items .Where(item => item.Type.GetItemInfo().IsComponent) .ToList() .ForEach(item => { foreach (var cargo in cargos) if (TryTransferTo(inventory, cargo, item)) break; }); }); } private static bool IsNotDisassembling(IMyProductionBlock block) { var assemblerBlock = block as IMyAssembler; if (assemblerBlock == null) return true; return assemblerBlock.Mode == MyAssemblerMode.Assembly; } private static void MoveIngotsToCargo( IReadOnlyCollection<IMyTerminalBlock> storageBlocks, IEnumerable<IMyProductionBlock> producingItemBlocks) { var cargos = storageBlocks.Where(IsIngotStorage).ToList(); if (!cargos.Any()) return; var productionBlockInventories = producingItemBlocks .Where(x => !IsIngotStorage(x)) .Select(b => b.OutputInventory); var storageBlockInventories = storageBlocks .Where(block => !(block is IMyProductionBlock)) .Where(block => !(block is IMyPowerProducer)) .Where(x => !IsIngotStorage(x)) .Select(b => b.GetInventory()); var inventories = productionBlockInventories .Concat(storageBlockInventories) .ToList(); inventories.ForEach(inventory => { var items = new List<MyInventoryItem>(); inventory.GetItems(items); items .Where(item => item.Type.GetItemInfo().IsIngot) .ToList() .ForEach(item => { foreach (var cargo in cargos) if (TryTransferTo(inventory, cargo, item)) break; }); }); } private static void MoveOresToCargo( IReadOnlyCollection<IMyTerminalBlock> storageBlocks, IEnumerable<IMyProductionBlock> producingItemBlocks) { var cargos = storageBlocks.Where(IsOreStorage).ToList(); if (!cargos.Any()) return; var productionBlockInventories = producingItemBlocks .Where(x => !IsOreStorage(x)) .Select(b => b.OutputInventory); var storageBlockInventories = storageBlocks .Where(block => !(block is IMyProductionBlock)) .Where(block => !(block is IMyGasGenerator)) .Where(x => !IsOreStorage(x)) .Select(b => b.GetInventory()); var inventories = productionBlockInventories .Concat(storageBlockInventories) .ToList(); inventories.ForEach(inventory => { var items = new List<MyInventoryItem>(); inventory.GetItems(items); items .Where(item => item.Type.GetItemInfo().IsOre) .ToList() .ForEach(item => { foreach (var cargo in cargos) if (TryTransferTo(inventory, cargo, item)) break; }); }); } private static bool IsComponentStorage(IMyTerminalBlock block) => Configuration.GetBlockConfiguration(block, Settings.DEFAULT_STORAGE_FOR_COMPONENTS) != null; private static bool IsAmmoStorage(IMyTerminalBlock block) => Configuration.GetBlockConfiguration(block, Settings.DEFAULT_STORAGE_FOR_AMMO) != null; private static bool IsToolStorage(IMyTerminalBlock block) => Configuration.GetBlockConfiguration(block, Settings.DEFAULT_STORAGE_FOR_TOOLS) != null; private static bool IsIngotStorage(IMyTerminalBlock block) => Configuration.GetBlockConfiguration(block, Settings.DEFAULT_STORAGE_FOR_INGOTS) != null; private static bool IsOreStorage(IMyTerminalBlock block) => Configuration.GetBlockConfiguration(block, Settings.DEFAULT_STORAGE_FOR_ORES) != null; private static void StackItems( IEnumerable<IMyTerminalBlock> storageBlocks, IEnumerable<IMyProductionBlock> producingItemBlocks) { var inventories = producingItemBlocks .Select(b => b.OutputInventory) .Concat(storageBlocks.Select(b => b.GetInventory())) .ToList(); inventories.ForEach(inventory => { var items = new List<MyInventoryItem>(); inventory.GetItems(items); for (var i = items.Count - 1; i >= 0; i--) { var item = items[i]; var firstOccurenceIndex = items.FindIndex(x => x.Type.TypeId == item.Type.TypeId && x.Type.SubtypeId == item.Type.SubtypeId); if (item.Type.GetItemInfo().MaxStackAmount > 1 && firstOccurenceIndex != i) inventory .TransferItemTo( inventory, i, firstOccurenceIndex, true ); } }); } private static bool TryTransferTo(IMyInventory inventory, IMyEntity cargo, MyInventoryItem item) => inventory.CanTransferItemTo(cargo.GetInventory(), item.Type) && inventory.TransferItemTo(cargo.GetInventory(), item); } 
 public interface IConfiguration { string GetConfig(string key); void SetConfig(string key, string value); } public class Configuration : IConfiguration { private readonly IMyTerminalBlock _block; private Dictionary<string, string> _settings; public Configuration(IMyTerminalBlock block) { _block = block; } string IConfiguration.GetConfig(string key) { Refresh(_block.CustomData); string value; return _settings.TryGetValue(key.ToLower().Trim(), out value) ? value : null; } void IConfiguration.SetConfig(string key, string value) { var sb = new StringBuilder(_block.CustomData); sb.AppendLine(string.IsNullOrEmpty(value) ? $"{key}" : $"{key}={value}"); _block.CustomData = sb.ToString(); } public static string GetBlockConfiguration(IMyTerminalBlock block, string key) { IConfiguration config = new Configuration(block); return config.GetConfig(key); } private void Refresh(string customData) { _settings = customData .Split(new[] { "\r\n", "\r", "\n" }, StringSplitOptions.None) .Where(row => row.Trim() != string.Empty) .ToDictionary( s => s.Split('=')[0].ToLower().Trim(), s => { var setting = s.Split('='); return setting.Length > 1 ? setting[1].ToLower().Trim() : ""; }); } } 
 public static class Settings { public const string EXCLUDE_FROM_AUTO_PRODUCTION = "exclude-from-auto-production"; public const string EXCLUDE_ITEM_FROM_STATS_INVENTORY = "hide-item"; public const string EXCLUDE_FROM_STATS_INVENTORY_WHEN_OVER_THRESHOLD = "exclude-when-over-threshold"; public const string STATS_STORAGE_CAPACITY = "stats-storage-capacity"; public const string STATS_POWER_USAGE = "stats-power-usage"; public const string STATS_HYDROGEN_USAGE = "stats-hydrogen-usage"; public const string STATS_IN_PRODUCTION = "stats-in-production"; public const string STATS_INVENTORY = "stats-inventory"; public const string STATS_INVENTORY_COMPONENTS = "stats-inventory-components"; public const string STATS_INVENTORY_ORES = "stats-inventory-ores"; public const string STATS_INVENTORY_INGOTS = "stats-inventory-ingots"; public const string STATS_INVENTORY_TOOLS = "stats-inventory-tools"; public const string STATS_INVENTORY_AMMUNITION = "stats-inventory-ammunition"; public const string DEFAULT_STORAGE_FOR_COMPONENTS = "component-default-storage"; public const string DEFAULT_STORAGE_FOR_INGOTS = "ingot-default-storage"; public const string DEFAULT_STORAGE_FOR_TOOLS = "tool-default-storage"; public const string DEFAULT_STORAGE_FOR_AMMO = "ammo-default-storage"; public const string DEFAULT_STORAGE_FOR_ORES = "ore-default-storage"; public const string IS_AIR_LOCK = "air-lock-group"; public const string LCD_WIDTH_RATIO = "lcd-width-ratio"; public const string AUTO_PRODUCE_ITEMS_ACTIVE = "auto-produce-items"; public const string AUTO_SHUTDOWN_DOORS_ACTIVE = "auto-shutdown-doors"; public const string AUTO_CLEANUP_STORAGES_ACTIVE = "auto-cleanup-storages"; public const string COMPONENT_THRESHOLD = "component-threshold"; public const string SHOW_POWER_USAGE_DETAILS = "show-power-usage-details"; } 
 public class DisplayManager { private readonly IMyGridAssistantLogger _logger; private readonly Dictionary<string, TopMarginInfo> _topMarginDictionary = new Dictionary<string, TopMarginInfo>(); public DisplayManager(IMyGridAssistantLogger logger) { _logger = logger; } public void Display( MonitoringData monitoringData, List<Item> itemsWithThreshold, IEnumerable<BlockEntity<IMyTerminalBlock>> textSurfacesBlocks) { var blockWithTextSurfaces = textSurfacesBlocks .Where(block => block.Exists()) .Select(block => block.Block) .ToList(); DisplayItemInventory(monitoringData, itemsWithThreshold, blockWithTextSurfaces); DisplayStorageCapacity(monitoringData, blockWithTextSurfaces); DisplayElectricalUsage(monitoringData, blockWithTextSurfaces); DisplayProduction(monitoringData, blockWithTextSurfaces); DisplayHydrogenStatistics(monitoringData, blockWithTextSurfaces); } private static List<Surface> GetDisplayBlocks( IEnumerable<IMyTerminalBlock> blocks, string customDataKeyToLookup) { var results = new List<Surface>(); foreach (var block in blocks) { IConfiguration configuration = new Configuration(block); var customData = configuration.GetConfig(customDataKeyToLookup); if (customData == null) continue; var index = 0; if (customData.Length > 0) int.TryParse(customData, out index); var textSurface = block as IMyTextSurfaceProvider; if (textSurface == null || textSurface.SurfaceCount <= index) continue; var result = new Surface { BlockId = block.EntityId, TextSurface = textSurface.GetSurface(index), Configuration = configuration }; results.Add(result); } return results; } private static void DisplayProduction(MonitoringData monitoringData, IEnumerable<IMyTerminalBlock> blocks) { var textBuilder = new StringBuilder(); textBuilder .AppendLine("** Currently in production **") .AppendLine(); monitoringData .GetItemsInProduction() .ForEach(inProd => { textBuilder.AppendLine(inProd.ItemType == Item.ItemTypes.Ingot ? $"{ToFriendlyQuantity(inProd.Amount / inProd.Volume)} {inProd.Name}" : $"{ToFriendlyQuantity(inProd.Amount)} {inProd.Name}"); }); var textSurfaceBlock = GetDisplayBlocks(blocks, Settings.STATS_IN_PRODUCTION); textSurfaceBlock.ForEach(block => block.TextSurface.WriteText(textBuilder)); } private static string ToFriendlyQuantity(float quantity) => quantity >= 1000 ? $"{quantity / 1000:0.##}K" : quantity.ToString("0.##"); private static void DisplayInventoryForTypes( Surface block, IEnumerable<Item> itemsToDisplay, IReadOnlyCollection<Item> itemsWithThreshold, MonitoringData monitoringData, IEnumerable<Item.ItemTypes> itemTypes) { var textBuilder = new StringBuilder(); var alreadyHasType = new Dictionary<Item.ItemTypes, bool>(); var hasSomethingToDisplay = false; itemsToDisplay .Where(i => itemTypes.Contains(i.ItemType)) .OrderBy(i => i.ItemType) .ThenByDescending(i => i.Amount) .ToList() .ForEach(item => { if (ShouldHideItem(block.Configuration, item)) return; if (ShouldHideBecauseMetThreshold(item, itemsWithThreshold, monitoringData, block.Configuration)) return; itemTypes .Where(i => i == item.ItemType) .OrderBy(i => i) .ToList() .ForEach(type => { if (!alreadyHasType.ContainsKey(type)) alreadyHasType.Add(type, false); alreadyHasType[type] = DisplayItems( type, item, alreadyHasType[type], textBuilder, ref hasSomethingToDisplay); }); }); block.TextSurface.WriteText(textBuilder); } private static bool ShouldHideBecauseMetThreshold( Item item, IReadOnlyCollection<Item> itemsWithThreshold, MonitoringData monitoringData, IConfiguration configuration) { var hideWhenMetThreshold = configuration.GetConfig(Settings.EXCLUDE_FROM_STATS_INVENTORY_WHEN_OVER_THRESHOLD) != null; var itemMetThreshold = IsItemMetThreshold( item, itemsWithThreshold, monitoringData); var itemHasThresholdDefined = HasItemThresholdDefined(item, itemsWithThreshold); return hideWhenMetThreshold && itemHasThresholdDefined && itemMetThreshold; } private static bool ShouldHideItem(IConfiguration customData, Item item) { var show = customData.GetConfig($"{Settings.EXCLUDE_ITEM_FROM_STATS_INVENTORY}-{item.ItemSubType}") == null; return show == false; } private static bool DisplayItems( Item.ItemTypes itemType, Item item, bool alreadyHasItem, StringBuilder textBuilder, ref bool hasSomethingToDisplay) { if (item.ItemType == itemType) if (!alreadyHasItem) { if (hasSomethingToDisplay) textBuilder.AppendLine(); textBuilder.AppendLine($"** Owned {itemType.ToString()} **"); alreadyHasItem = true; } hasSomethingToDisplay = true; textBuilder.AppendLine($"{ToFriendlyQuantity(item.Amount)} {item.Name}"); return alreadyHasItem; } private static void DisplayItemInventory( MonitoringData monitoringData, IReadOnlyCollection<Item> itemsWithThreshold, IReadOnlyCollection<IMyTerminalBlock> blocks) { var itemsToDisplay = BuildItemsToDisplay(monitoringData.GetItems(), itemsWithThreshold); var displayAllSurfaceBlocks = GetDisplayBlocks(blocks, Settings.STATS_INVENTORY); var displayComponentSurfaceBlocks = GetDisplayBlocks(blocks, Settings.STATS_INVENTORY_COMPONENTS); var displayOreSurfaceBlocks = GetDisplayBlocks(blocks, Settings.STATS_INVENTORY_ORES); var displayIngotSurfaceBlocks = GetDisplayBlocks(blocks, Settings.STATS_INVENTORY_INGOTS); var displayToolsSurfaceBlocks = GetDisplayBlocks(blocks, Settings.STATS_INVENTORY_TOOLS); var displayAmmunitionSurfaceBlocks = GetDisplayBlocks(blocks, Settings.STATS_INVENTORY_AMMUNITION); var surfaceByTypes = Combine( displayAllSurfaceBlocks, displayComponentSurfaceBlocks, displayOreSurfaceBlocks, displayIngotSurfaceBlocks, displayToolsSurfaceBlocks, displayAmmunitionSurfaceBlocks); surfaceByTypes.ForEach(surfaceByType => { DisplayInventoryForTypes( surfaceByType.Surface, itemsToDisplay, itemsWithThreshold, monitoringData, surfaceByType.ItemTypes); }); } private static List<SurfaceByType> Combine( IEnumerable<Surface> allSurfaceBlocks, IEnumerable<Surface> componentSurfaceBlocks, IEnumerable<Surface> oreSurfaceBlocks, IEnumerable<Surface> ingotSurfaceBlocks, IEnumerable<Surface> toolsSurfaceBlocks, IEnumerable<Surface> ammunitionSurfaceBlocks) { var allSurfaces = allSurfaceBlocks.Select(surface => new SurfaceByType { Surface = surface, ItemTypes = new[] { Item.ItemTypes.Ammunition, Item.ItemTypes.Component, Item.ItemTypes.Consumable, Item.ItemTypes.Ingot, Item.ItemTypes.Ore, Item.ItemTypes.Tools, Item.ItemTypes.Unknown } }) .Concat(componentSurfaceBlocks.Select(surface => new SurfaceByType { Surface = surface, ItemTypes = new[] { Item.ItemTypes.Component, Item.ItemTypes.Unknown } })) .Concat(oreSurfaceBlocks.Select(surface => new SurfaceByType { Surface = surface, ItemTypes = new[] { Item.ItemTypes.Ore, Item.ItemTypes.Unknown } })) .Concat(ingotSurfaceBlocks.Select(surface => new SurfaceByType { Surface = surface, ItemTypes = new[] { Item.ItemTypes.Ingot, Item.ItemTypes.Unknown } })) .Concat(toolsSurfaceBlocks.Select(surface => new SurfaceByType { Surface = surface, ItemTypes = new[] { Item.ItemTypes.Tools, Item.ItemTypes.Unknown } })) .Concat(ammunitionSurfaceBlocks.Select(surface => new SurfaceByType { Surface = surface, ItemTypes = new[] { Item.ItemTypes.Ammunition, Item.ItemTypes.Unknown } })) .ToList(); var dictionary = new Dictionary<long, SurfaceByType>(); foreach (var surfaceByType in allSurfaces) if (dictionary.ContainsKey(surfaceByType.Surface.BlockId)) { var actualTypes = dictionary[surfaceByType.Surface.BlockId].ItemTypes.ToList(); var typesToAdd = surfaceByType.ItemTypes.ToList(); var newItemTypes = new List<Item.ItemTypes>(actualTypes); foreach (var itemType in typesToAdd.Where(itemType => !newItemTypes.Exists(newItemType => newItemType == itemType))) newItemTypes.Add(itemType); dictionary[surfaceByType.Surface.BlockId].ItemTypes = newItemTypes; } else { var typesToAdd = surfaceByType.ItemTypes.ToList(); dictionary.Add( surfaceByType.Surface.BlockId, new SurfaceByType { Surface = surfaceByType.Surface, ItemTypes = typesToAdd }); } return dictionary.Select(d => new SurfaceByType { Surface = allSurfaces.First(b => b.Surface.BlockId == d.Key).Surface, ItemTypes = d.Value.ItemTypes }) .ToList(); } private static List<Item> BuildItemsToDisplay( ICollection<Item> itemsInInventory, IEnumerable<Item> itemsWithThreshold) { var result = new List<Item>(itemsInInventory); foreach (var itemWithThreshold in itemsWithThreshold) { var isItemWithThresholdFound = itemsInInventory.Any(itemToDisplay => itemToDisplay.IsSameAs(itemWithThreshold)); if (!isItemWithThresholdFound) itemsInInventory.Add(new Item(itemWithThreshold.ItemDefinitionId, 0)); } return result.OrderBy(item => item.ItemType).ThenBy(item => item.Name).ToList(); } private static bool HasItemThresholdDefined(Item item, IEnumerable<Item> itemsWithThreshold) { return itemsWithThreshold.Any(itemWithThreshold => itemWithThreshold.ItemType == item.ItemType && itemWithThreshold.ItemSubType == item.ItemSubType); } private static bool IsItemMetThreshold( Item itemToDisplay, IEnumerable<Item> itemsWithThreshold, MonitoringData data) { var item = itemsWithThreshold.FirstOrDefault(itemWithThreshold => itemWithThreshold.ItemType == itemToDisplay.ItemType && itemWithThreshold.ItemSubType == itemToDisplay.ItemSubType); if (item == null) return true; var inventoryCount = data.GetItems() .Where(i => i.ItemType == itemToDisplay.ItemType && i.ItemSubType == itemToDisplay.ItemSubType) .Sum(x => x.Amount); return inventoryCount >= item.Amount; } private void DisplayStorageCapacity( MonitoringData monitoringData, IEnumerable<IMyTerminalBlock> blocks) { const float LEFT_MARGIN = 10f; var textSurfaceBlock = GetDisplayBlocks(blocks, Settings.STATS_STORAGE_CAPACITY); textSurfaceBlock.ForEach(surface => { var topMargin = GetTopMargin(surface.BlockId, surface.TextSurface.Name); var keepRatio = surface.Configuration.GetConfig(Settings.LCD_WIDTH_RATIO) != null; var textSurface = surface.TextSurface; var engin = new GraphicEngine(textSurface, keepRatio, _logger); var fullBarSize = textSurface.SurfaceSize.X - LEFT_MARGIN * 2; var smallBarSize = textSurface.SurfaceSize.X - 30f - LEFT_MARGIN * 2; engin.BackgroundColor = new Color(0, 0, 0, 255); var fillRatio = monitoringData.Cargos.Sum(c => (float)c.MaxVolume) == 0 ? 0 : monitoringData.Cargos.Sum(c => (float)c.CurrentVolume) / monitoringData.Cargos.Sum(c => (float)c.MaxVolume); var currentYPos = engin.AddProgressBar( "Storage Capacity", fullBarSize, 30f, 1f, LEFT_MARGIN, topMargin, fillRatio ); currentYPos += 10f; monitoringData.Cargos .OrderBy(b => b.Name) .ToList() .ForEach(cargo => { double fill = cargo.MaxVolume.ToIntSafe() == 0 ? 0 : (float)cargo.CurrentVolume / cargo.MaxVolume.ToIntSafe(); currentYPos = engin.AddProgressBar( cargo.Name, smallBarSize, 5f, .50f, LEFT_MARGIN + 30f, currentYPos + 1f, fill ); }); SetTopMargin(surface.BlockId, textSurface.Name, currentYPos, textSurface.SurfaceSize.Y); engin.Draw(); }); } private void DisplayElectricalUsage(MonitoringData monitoringData, IEnumerable<IMyTerminalBlock> blocks) { const float LEFT_MARGIN = 10f; const float GAP_BETWEEN_SECTIONS = 20f; var textSurfaceBlock = GetDisplayBlocks(blocks, Settings.STATS_POWER_USAGE); textSurfaceBlock.ForEach(surface => { var withDetails = surface.Configuration.GetConfig(Settings.SHOW_POWER_USAGE_DETAILS) != null; var topMargin = GetTopMargin(surface.BlockId, surface.TextSurface.Name); var keepRatio = surface.Configuration.GetConfig(Settings.LCD_WIDTH_RATIO) != null; var textSurface = surface.TextSurface; var engin = new GraphicEngine(textSurface, keepRatio, _logger); var fullBarSize = textSurface.SurfaceSize.X - LEFT_MARGIN * 2; var mediumBarSize = textSurface.SurfaceSize.X - 20f - LEFT_MARGIN * 2; var smallBarSize = textSurface.SurfaceSize.X - 30f - LEFT_MARGIN * 2; engin.BackgroundColor = new Color(0, 0, 0, 255); var currentYPos = engin.AddProgressBar( "Electrical Consumption", fullBarSize, 30f, 1f, LEFT_MARGIN, topMargin, monitoringData.PowerConsumption.CurrentPowerOutput / monitoringData.PowerConsumption.MaxPowerOutput ); currentYPos += 10f; if (monitoringData.PowerConsumption.WindTurbines.Any()) { var currentOutput = monitoringData.PowerConsumption.WindTurbines.Sum(t => t.CurrentOutput); var currentTotalOutput = monitoringData.PowerConsumption.CurrentPowerOutput; double fillRatio = currentTotalOutput == 0 ? 0 : currentOutput / currentTotalOutput; currentYPos = engin.AddProgressBar( $"[{monitoringData.PowerConsumption.WindTurbines.Count}] Wind Turbines", mediumBarSize, 22f, .75f, LEFT_MARGIN + 20f, currentYPos + GAP_BETWEEN_SECTIONS, fillRatio ); currentYPos += 5f; var currentTotalTurbineOutput = monitoringData.PowerConsumption.WindTurbines.Sum(t => t.CurrentOutput); if (withDetails) monitoringData.PowerConsumption.WindTurbines .OrderBy(x => x.Name) .ToList() .ForEach(turbine => { double fill = currentTotalTurbineOutput == 0 ? 0 : turbine.CurrentOutput / currentTotalTurbineOutput; currentYPos = engin.AddProgressBar( turbine.Name, smallBarSize, 5f, .50f, LEFT_MARGIN + 30f, currentYPos + 1f, fill ); }); } if (monitoringData.PowerConsumption.SolarPanels.Any()) { var currentOutput = monitoringData.PowerConsumption.SolarPanels.Sum(t => t.CurrentOutput); var currentTotalOutput = monitoringData.PowerConsumption.CurrentPowerOutput; double fillRatio = currentTotalOutput == 0 ? 0 : currentOutput / currentTotalOutput; currentYPos = engin.AddProgressBar( $"[{monitoringData.PowerConsumption.SolarPanels.Count}] Solar Panels", mediumBarSize, 22f, .75f, LEFT_MARGIN + 20f, currentYPos + GAP_BETWEEN_SECTIONS, fillRatio ); currentYPos += 5f; var currentTotalSolarPanelsOutput = monitoringData.PowerConsumption.SolarPanels.Sum(t => t.CurrentOutput); if (withDetails) monitoringData.PowerConsumption.SolarPanels .OrderBy(x => x.Name) .ToList() .ForEach(solarPanel => { double fill = currentTotalSolarPanelsOutput == 0 ? 0 : solarPanel.CurrentOutput / currentTotalSolarPanelsOutput; currentYPos = engin.AddProgressBar( solarPanel.Name, smallBarSize, 5f, .50f, LEFT_MARGIN + 30f, currentYPos + 1f, fill ); }); } if (monitoringData.PowerConsumption.Batteries.Any()) { var currentOutput = monitoringData.PowerConsumption.Batteries.Sum(t => t.CurrentOutput); var currentTotalOutput = monitoringData.PowerConsumption.CurrentPowerOutput; double fillRatio = currentTotalOutput == 0 ? 0 : currentOutput / currentTotalOutput; currentYPos = engin.AddProgressBar( $"[{monitoringData.PowerConsumption.Batteries.Count}] Batteries", mediumBarSize, 22f, .75f, LEFT_MARGIN + 20f, currentYPos + GAP_BETWEEN_SECTIONS, fillRatio ); currentYPos += 5f; var currentTotalBatteriesOutput = monitoringData.PowerConsumption.Batteries.Sum(t => t.CurrentOutput); if (withDetails) monitoringData.PowerConsumption.Batteries .OrderBy(x => x.Name) .ToList() .ForEach(battery => { double fill = currentTotalBatteriesOutput == 0 ? 0 : battery.CurrentOutput / currentTotalBatteriesOutput; currentYPos = engin.AddProgressBar( battery.Name, smallBarSize, 5f, .50f, LEFT_MARGIN + 30f, currentYPos + 1f, fill ); }); currentYPos += 10f; engin.AddSprite( "IconEnergy", 15, 15, LEFT_MARGIN + 10f, currentYPos, TextAlignment.LEFT, 0f, false, Color.Yellow ); currentYPos = engin.AddText( "Stored Power", .75f, LEFT_MARGIN + 30f, currentYPos, TextAlignment.LEFT ); currentYPos += 5f; monitoringData.PowerConsumption.Batteries .OrderBy(x => x.Name) .ToList() .ForEach(battery => { double fill = battery.MaxStoredPower == 0 ? 0 : battery.CurrentStoredPower / battery.MaxStoredPower; currentYPos = engin.AddProgressBar( battery.Name, smallBarSize, 5f, .50f, LEFT_MARGIN + 30f, currentYPos + 1f, fill, battery.IsCharging ? Color.Green : Color.Red ); }); monitoringData.ForeignPowerConsumption.Batteries .OrderBy(x => x.Name) .ToList() .ForEach(battery => { double fill = battery.MaxStoredPower == 0 ? 0 : battery.CurrentStoredPower / battery.MaxStoredPower; if (fill < .99f) currentYPos = engin.AddProgressBar( battery.Name, smallBarSize, 5f, .50f, LEFT_MARGIN + 30f, currentYPos + 1f, fill, battery.IsCharging ? Color.DarkGreen : Color.DarkRed ); }); } if (monitoringData.PowerConsumption.Reactors.Any()) { var currentOutput = monitoringData.PowerConsumption.Reactors.Sum(t => t.CurrentOutput); var currentTotalOutput = monitoringData.PowerConsumption.CurrentPowerOutput; double fillRatio = currentTotalOutput == 0 ? 0 : currentOutput / currentTotalOutput; currentYPos = engin.AddProgressBar( $"[{monitoringData.PowerConsumption.Reactors.Count}] Reactors", mediumBarSize, 22f, .75f, LEFT_MARGIN + 20f, currentYPos + GAP_BETWEEN_SECTIONS, fillRatio ); currentYPos += 5f; engin.AddText( $"Available Uranium Ingots: {monitoringData.PowerConsumption.AvailableUranium.ToString()}", .75f, LEFT_MARGIN + 50f, currentYPos, TextAlignment.LEFT ); currentYPos = engin.AddSprite( "MyObjectBuilder_Ingot/Uranium", 15, 15, LEFT_MARGIN + 30f, currentYPos, TextAlignment.LEFT, 0f, false, new Color(26, 174, 122, 255) ); currentYPos += 10f; var currentTotalReactorsOutput = monitoringData.PowerConsumption.Reactors.Sum(t => t.CurrentOutput); if (withDetails) monitoringData.PowerConsumption.Reactors .OrderBy(x => x.Name) .ToList() .ForEach(reactor => { double fill = currentTotalReactorsOutput == 0 ? 0 : reactor.CurrentOutput / currentTotalReactorsOutput; currentYPos = engin.AddProgressBar( reactor.Name, smallBarSize, 5f, .50f, LEFT_MARGIN + 30f, currentYPos + 1f, fill ); }); } if (monitoringData.PowerConsumption.HydrogenEngines.Any()) { var currentOutput = monitoringData.PowerConsumption.HydrogenEngines.Sum(t => t.CurrentOutput); var currentTotalOutput = monitoringData.PowerConsumption.CurrentPowerOutput; double fillRatio = currentTotalOutput == 0 ? 0 : currentOutput / currentTotalOutput; currentYPos = engin.AddProgressBar( $"[{monitoringData.PowerConsumption.HydrogenEngines.Count}] - Hydrogen Engines", mediumBarSize, 22f, .75f, LEFT_MARGIN + 20f, currentYPos + GAP_BETWEEN_SECTIONS, fillRatio ); currentYPos += 5f; engin.AddText( $"Available Ice Ore: {monitoringData.PowerConsumption.AvailableIce.ToString()}", .75f, LEFT_MARGIN + 50f, currentYPos, TextAlignment.LEFT ); currentYPos = engin.AddSprite( "MyObjectBuilder_Ore/Ice", 15, 15, LEFT_MARGIN + 30f, currentYPos, TextAlignment.LEFT, 0f, false, new Color(255, 255, 255, 255) ); var hydroFillRatio = monitoringData.HydrogenTanks.Sum(h => h.FilledRatio); var availableTank = monitoringData.HydrogenTanks.Count; var ratio = availableTank == 0 ? 0 : hydroFillRatio / availableTank; engin.AddText( $"Available Hydrogen in tanks: {ratio * 100:F2} %", .75f, LEFT_MARGIN + 50f, currentYPos + 1f, TextAlignment.LEFT ); currentYPos = engin.AddSprite( "IconHydrogen", 15, 15, LEFT_MARGIN + 30f, currentYPos + 1f, TextAlignment.LEFT, 0f, false, new Color(61, 165, 244, 255) ); currentYPos += 10f; var currentTotalEngineOutput = monitoringData.PowerConsumption.HydrogenEngines.Sum(t => t.CurrentOutput); if (withDetails) monitoringData.PowerConsumption.HydrogenEngines .OrderBy(x => x.Name) .ToList() .ForEach(engine => { double fill = currentTotalEngineOutput == 0 ? 0 : engine.CurrentOutput / currentTotalEngineOutput; currentYPos = engin.AddProgressBar( engine.Name, smallBarSize, 5f, .50f, LEFT_MARGIN + 30f, currentYPos + 1f, fill ); }); } SetTopMargin(surface.BlockId, textSurface.Name, currentYPos, textSurface.SurfaceSize.Y); engin.Draw(); }); } private void SetTopMargin( long surfaceBlockId, string surfaceName, float currentYPos, float surfaceHeight) { var key = $"{surfaceBlockId.ToString()}-{surfaceName}"; var marginInfo = _topMarginDictionary[key]; if (marginInfo.Direction == Directions.Forward) { if (currentYPos > surfaceHeight - 10f) marginInfo.CurrentMargin -= 5f; else marginInfo.Direction = Directions.Backward; } else { if (marginInfo.CurrentMargin == 10f) marginInfo.Direction = Directions.Forward; else marginInfo.CurrentMargin += 5f; } _topMarginDictionary[key] = marginInfo; } private float GetTopMargin(long surfaceBlockId, string surfaceName) { var key = $"{surfaceBlockId.ToString()}-{surfaceName}"; if (!_topMarginDictionary.ContainsKey(key)) _topMarginDictionary.Add( key, new TopMarginInfo { Direction = Directions.Forward, CurrentMargin = 10f }); return _topMarginDictionary[key].CurrentMargin; } private void DisplayHydrogenStatistics( MonitoringData monitoringData, IEnumerable<IMyTerminalBlock> blocks) { var textSurfaceBlock = GetDisplayBlocks(blocks, Settings.STATS_HYDROGEN_USAGE); textSurfaceBlock.ForEach(surface => { var topMargin = GetTopMargin(surface.BlockId, surface.TextSurface.Name); const float GAP_BETWEEN_SECTIONS = 20f; const float LEFT_MARGIN = 10f; const float ICON_SIZE = 30f; const float BAR_LEFT_BEGIN = LEFT_MARGIN + ICON_SIZE; var isFirst = true; var ratio = surface.Configuration.GetConfig(Settings.LCD_WIDTH_RATIO) != null; var textSurface = surface.TextSurface; var engin = new GraphicEngine(textSurface, ratio, _logger); var barSize = textSurface.SurfaceSize.X - 90f; engin.BackgroundColor = new Color(0, 0, 0, 255); var currentYPos = topMargin; foreach (var tank in monitoringData.HydrogenTanks.OrderBy(x => x.Name)) { if (isFirst == false) currentYPos += GAP_BETWEEN_SECTIONS; var rowYPos = engin.AddProgressBar( tank.Name, barSize, 30f, 1f, BAR_LEFT_BEGIN, currentYPos, tank.FilledRatio); engin.AddSprite( "IconHydrogen", ICON_SIZE, ICON_SIZE, LEFT_MARGIN, currentYPos + 25f, TextAlignment.LEFT, 0f, false, new Color(61, 165, 244, 255) ); isFirst = false; currentYPos = rowYPos; } currentYPos += 5f; engin.AddText( $"Available Ice Ore: {monitoringData.PowerConsumption.AvailableIce.ToString()}", .75f, LEFT_MARGIN + 50f, currentYPos, TextAlignment.LEFT ); currentYPos = engin.AddSprite( "MyObjectBuilder_Ore/Ice", 15, 15, LEFT_MARGIN + 30f, currentYPos, TextAlignment.LEFT, 0f, false, new Color(255, 255, 255, 255) ); var hydroFillRatio = monitoringData.HydrogenTanks.Sum(h => h.FilledRatio); var availableTank = monitoringData.HydrogenTanks.Count; var hydrogenRatio = availableTank == 0 ? 0 : hydroFillRatio / availableTank; engin.AddText( $"Available Hydrogen in tanks: {hydrogenRatio * 100:F2} %", .75f, LEFT_MARGIN + 50f, currentYPos + 1f, TextAlignment.LEFT ); currentYPos = engin.AddSprite( "IconHydrogen", 15, 15, LEFT_MARGIN + 30f, currentYPos + 1f, TextAlignment.LEFT, 0f, false, new Color(61, 165, 244, 255) ); SetTopMargin(surface.BlockId, textSurface.Name, currentYPos, textSurface.SurfaceSize.Y); engin.Draw(); }); } private enum Directions { Forward, Backward } private class TopMarginInfo { public Directions Direction { get; set; } public float CurrentMargin { get; set; } } } 
 public class GraphicEngine { private readonly Color _defaultTextColor = new Color(171, 146, 91, 255); private readonly IMyGridAssistantLogger _logger; private readonly float _ratio; private readonly List<MySprite> _sprites = new List<MySprite>(); private readonly IMyTextSurface _textSurface; private readonly float _yOffset; public GraphicEngine(IMyTextSurface textSurface, bool screenSizeRatio, IMyGridAssistantLogger logger) { _textSurface = textSurface; _logger = logger; _ratio = screenSizeRatio ? textSurface.SurfaceSize.Y / textSurface.SurfaceSize.X : 1f; _yOffset = Math.Abs(textSurface.SurfaceSize.Y / textSurface.SurfaceSize.X - 1f) > 0 ? (textSurface.SurfaceSize.X - textSurface.SurfaceSize.Y) / 2 : 0; } public Color? BackgroundColor { get; set; } public void Draw() { using (var frame = _textSurface.DrawFrame()) { var bgColor = BackgroundColor ?? _textSurface.ScriptBackgroundColor; { var sprite = new MySprite( SpriteType.TEXTURE, "SquareSimple", size: new Vector2(512.0f, 512.0f * _ratio), color: bgColor); frame.Add(sprite); } frame.AddRange(_sprites); } } public float AddText( string text, float scale, float left, float top, TextAlignment alignment, Color? color = null) { if (color == null) color = _defaultTextColor; const float Y_MARGIN = -5f; const float TEXT_BOX_SIZE = 20f; var sprite = MySprite.CreateText( text, "debug", color.Value, scale * _ratio, alignment); sprite.Position = new Vector2( left, top + _yOffset + Y_MARGIN * _ratio); _sprites.Add(sprite); return top + TEXT_BOX_SIZE * (scale * _ratio) + 1f; } public float AddSprite( string spriteId, float width, float height, float left, float top, TextAlignment alignment, float rotation, bool preserveRatio, Color? color = null) { var sizeX = width * (preserveRatio ? _ratio : 1); var sizeY = height * _ratio; var posY = top + _yOffset; var sprite = new MySprite( SpriteType.TEXTURE, spriteId, new Vector2(left, posY + sizeY / 2), new Vector2(sizeX, sizeY), color, null, alignment, rotation ); _sprites.Add(sprite); return top + sizeY + 1f; } public float AddProgressBar( string text, float width, float barHeight, float textScale, float left, float top, double fillRatio, Color? color = null) { if (color == null) color = new Color(61, 165, 244); var textLeftBegin = left + 30f; var margin = 5f * textScale; var barTop = AddText( text, textScale, textLeftBegin, top, TextAlignment.LEFT ); var barEnd = AddSprite( "SquareSimple", width, barHeight, left, barTop + margin, TextAlignment.LEFT, 0f, false, new Color(47, 50, 52, 255) ); AddSprite( "SquareSimple", Convert.ToSingle(fillRatio) * width, barHeight, left, barTop + margin, TextAlignment.LEFT, 0f, false, color.Value ); AddSprite( "SquareSimple", 3f, barHeight, left + width / 4, barTop + margin, TextAlignment.LEFT, 0f, false, new Color(0, 0, 0, 255) ); AddSprite( "SquareSimple", 3f, barHeight, left + width / 4 * 2, barTop + margin, TextAlignment.LEFT, 0f, false, new Color(0, 0, 0, 255) ); AddSprite( "SquareSimple", 3f, barHeight, left + width / 4 * 3, barTop + margin, TextAlignment.LEFT, 0f, false, new Color(0, 0, 0, 255) ); AddText( (fillRatio * 100).ToString("F2") + "%", textScale * .75f, width + left, 7f * textScale + top, TextAlignment.RIGHT, color.Value); return barEnd + 1; } } 
