 public class DoorManager { private const int ALLOWED_OPEN_SECOND = 5; private readonly Dictionary<long, DateTime> _doorOpenedCount = new Dictionary<long, DateTime>(); private readonly IMyGridAssistantLogger _logger; public DoorManager(IMyGridAssistantLogger logger) { _logger = logger; } public void ShutDownDoorWhenOpenedLongerThanExpected(IEnumerable<BlockEntity<IMyDoor>> doors) { var doorsToScan = doors .Where(door => door.Exists()) .Select(door => door.Block) .ToList(); foreach (var door in doorsToScan) { if (!_doorOpenedCount.ContainsKey(door.EntityId)) _doorOpenedCount.Add(door.EntityId, DateTime.Now); if (door.Status == DoorStatus.Closed) { _doorOpenedCount[door.EntityId] = DateTime.Now; } else { var totalSeconds = DateTime.Now.Subtract(_doorOpenedCount[door.EntityId]).TotalSeconds; if (totalSeconds > ALLOWED_OPEN_SECOND) door.CloseDoor(); } } } public void ManageAirLocks(IEnumerable<BlockEntity<IMyDoor>> doors) { var doorsToScan = doors .Where(door => door.Exists()) .Select(door => door.Block) .ToList(); var airlockDictionary = new Dictionary<string, List<IMyDoor>>(); doorsToScan.ForEach(door => { var group = Configuration.GetBlockConfiguration(door, Settings.IS_AIR_LOCK); if (group == null) return; var airlocks = new List<IMyDoor>(); if (airlockDictionary.ContainsKey(group)) airlocks = airlockDictionary[group]; else airlockDictionary.Add(group, new List<IMyDoor>()); if (airlocks.Count > 2) return; airlocks.Add(door); airlockDictionary[group] = airlocks; }); airlockDictionary .Where(airlock => airlock.Value.Count == 2) .ToList() .ForEach(d => { var door1 = d.Value[0]; var door2 = d.Value[1]; door1.ApplyAction(door2.Status != DoorStatus.Closed ? "OnOff_Off" : "OnOff_On"); door2.ApplyAction(door1.Status != DoorStatus.Closed ? "OnOff_Off" : "OnOff_On"); }); } } 
 public class LogEntry { public DateTime DateCreated { get; set; } public string Message { get; set; } public int Expiry { get; set; } } 
 public interface IMyGridAssistantLogger { void LogDebug(string message, int expireInSecond = 5); void LogInfo(string logId, string message); void ShowLogs(); } public class MyGridAssistantLogger : IMyGridAssistantLogger { private readonly Action<string> _log; private readonly Dictionary<string, string> _logDictionary; private List<LogEntry> _timedLogs; public MyGridAssistantLogger(Action<string> log) { _log = log; _timedLogs = new List<LogEntry>(); _logDictionary = new Dictionary<string, string>(); } public void LogDebug(string message, int expireInSecond = 5) { var logEntry = new LogEntry { DateCreated = DateTime.Now, Message = message, Expiry = expireInSecond }; _timedLogs.Insert(0, logEntry); } public void LogInfo(string logId, string message) { if (_logDictionary.ContainsKey(logId)) _logDictionary[logId] = message; else _logDictionary.Add(logId, message); } public void ShowLogs() { var now = DateTime.Now; _timedLogs = _timedLogs.Where(log => now.Subtract(log.DateCreated).Seconds <= log.Expiry).ToList(); var debugLogs = _timedLogs.Select(log => log.Message); var logs = _logDictionary.Select(log => log.Value); var result = new StringBuilder(string.Join(Environment.NewLine, debugLogs)) .AppendLine() .AppendLine("-----------") .Append(string.Join(Environment.NewLine, logs)) .ToString(); _log(result); } } 
 public class CargoInfo { public string Name { get; set; } public MyFixedPoint MaxVolume { get; set; } public MyFixedPoint CurrentVolume { get; set; } } 
 public class GridMonitoring { private readonly IMyGridAssistantLogger _logger; public GridMonitoring(IMyGridAssistantLogger logger) { _logger = logger; MonitoringData = new MonitoringData(_logger); } public MonitoringData MonitoringData { get; } public void UpdateData( IEnumerable<BlockEntity<IMyPowerProducer>> powerBlocks, IEnumerable<BlockEntity<IMyPowerProducer>> foreignPowerBlocks, List<BlockEntity<IMyTerminalBlock>> withStorageBlocks, IEnumerable<BlockEntity<IMyProductionBlock>> productionBlocks, IEnumerable<BlockEntity<IMyGasTank>> gasTanks) { MonitoringData.Reset(); ScanStorageCapacity(withStorageBlocks); ScanAllInventory(withStorageBlocks); ScanPower(powerBlocks); ScanForeignPower(foreignPowerBlocks); ScanProduction(productionBlocks); ScanHydrogen(gasTanks); } private void ScanHydrogen(IEnumerable<BlockEntity<IMyGasTank>> gasTanks) { MonitoringData.HydrogenTanks.AddRange(gasTanks .Where(block => block.Exists()) .Select(block => block.Block) .Where(tank => tank.BlockDefinition.SubtypeName.ToUpper().Contains("HYDROGEN")) .Select(tank => new HydrogenTankInfo { Name = tank.CustomName, Capacity = tank.Capacity, FilledRatio = tank.FilledRatio } )); _logger.LogInfo("GridMonitoring.ScanHydrogen_1", ""); _logger.LogInfo("GridMonitoring.ScanHydrogen_2", "** Hydrogen **"); _logger.LogInfo("GridMonitoring.ScanHydrogen_3", $"Current Hydrogen Capacity: {MonitoringData.HydrogenTanks.Sum(h => h.Capacity):0.##}"); _logger.LogInfo("GridMonitoring.ScanHydrogen_4", $"Current Hydrogen Filled Ratio: {MonitoringData.HydrogenTanks.Sum(h => h.FilledRatio) / MonitoringData.HydrogenTanks.Count:0.##} %"); } private void ScanPower(IEnumerable<BlockEntity<IMyPowerProducer>> powerBlocks) { var uraniumCount = MonitoringData.GetItems(Item.ItemTypes.Ingot) .Where(i => i.ItemSubType == Item.ItemSubTypes.Uranium) .Sum(i => i.Amount); var iceCount = MonitoringData.GetItems(Item.ItemTypes.Ore) .Where(i => i.ItemSubType == Item.ItemSubTypes.Ice) .Sum(i => i.Amount); MonitoringData.PowerConsumption.AvailableUranium = uraniumCount; MonitoringData.PowerConsumption.AvailableIce = iceCount; powerBlocks .Where(block => block.Exists()) .Select(block => block.Block) .ToList() .ForEach(block => { var battery = block as IMyBatteryBlock; var solarPanel = block as IMySolarPanel; var reactor = block as IMyReactor; if (battery != null) MonitoringData.PowerConsumption.Batteries.Add(new BatteryInfo { Name = battery.CustomName, IsCharging = battery.IsCharging, CurrentStoredPower = battery.CurrentStoredPower, MaxStoredPower = battery.MaxStoredPower, CurrentOutput = battery.CurrentOutput, MaxOutput = battery.MaxOutput }); if (solarPanel != null) MonitoringData.PowerConsumption.SolarPanels.Add(new SolarPanelInfo { Name = solarPanel.CustomName, CurrentOutput = solarPanel.CurrentOutput, MaxOutput = solarPanel.MaxOutput }); if (reactor != null) MonitoringData.PowerConsumption.Reactors.Add(new ReactorInfo { Name = reactor.CustomName, CurrentOutput = reactor.CurrentOutput, MaxOutput = reactor.MaxOutput }); if (block.GetType().Name.IndexOf("MyHydrogenEngine", StringComparison.InvariantCultureIgnoreCase) >= 0) MonitoringData.PowerConsumption.HydrogenEngines.Add(new HydrogenEngineInfo { Name = block.CustomName, CurrentOutput = block.CurrentOutput, MaxOutput = block.MaxOutput, FilledRatio = (block as IMyGasTank)?.FilledRatio ?? 0 }); if (block.GetType().Name.IndexOf("MyWindTurbine", StringComparison.InvariantCultureIgnoreCase) >= 0) MonitoringData.PowerConsumption.WindTurbines.Add(new WindTurbineInfo { Name = block.CustomName, CurrentOutput = block.CurrentOutput, MaxOutput = block.MaxOutput }); }); _logger.LogInfo("GridMonitoring.ScanPower_1", ""); _logger.LogInfo("GridMonitoring.ScanPower_2", "** Power **"); _logger.LogInfo("GridMonitoring.ScanPower_3", $"Battery Count: {MonitoringData.PowerConsumption.Batteries.Count}"); _logger.LogInfo("GridMonitoring.ScanPower_4", $"Solar Panel Count: {MonitoringData.PowerConsumption.SolarPanels.Count}"); _logger.LogInfo("GridMonitoring.ScanPower_5", $"Reactor Count: {MonitoringData.PowerConsumption.Reactors.Count}"); _logger.LogInfo("GridMonitoring.ScanPower_6", $"Hydrogen Engine Count: {MonitoringData.PowerConsumption.HydrogenEngines.Count}"); _logger.LogInfo("GridMonitoring.ScanPower_7", $"Wind Turret Count: {MonitoringData.PowerConsumption.WindTurbines.Count}"); _logger.LogInfo("GridMonitoring.ScanPower_8", ""); _logger.LogInfo("GridMonitoring.ScanPower_9", $"Current Power Output: {MonitoringData.PowerConsumption.CurrentPowerOutput} MW"); _logger.LogInfo("GridMonitoring.ScanPower_10", $"Max Power Output: {MonitoringData.PowerConsumption.MaxPowerOutput} MW"); _logger.LogInfo("GridMonitoring.ScanPower_11", ""); _logger.LogInfo("GridMonitoring.ScanPower_12", $"Available Uranium: {MonitoringData.PowerConsumption.AvailableUranium}"); _logger.LogInfo("GridMonitoring.ScanPower_13", $"Available Ice: {MonitoringData.PowerConsumption.AvailableIce}"); } private void ScanForeignPower(IEnumerable<BlockEntity<IMyPowerProducer>> powerBlocks) { powerBlocks .Where(block => block.Exists()) .Select(block => block.Block) .ToList() .ForEach(block => { var battery = block as IMyBatteryBlock; if (battery != null) MonitoringData.ForeignPowerConsumption.Batteries.Add(new BatteryInfo { Name = battery.CustomName, IsCharging = battery.IsCharging, CurrentStoredPower = battery.CurrentStoredPower, MaxStoredPower = battery.MaxStoredPower, CurrentOutput = battery.CurrentOutput, MaxOutput = battery.MaxOutput }); }); _logger.LogInfo("GridMonitoring.ScanForeignPower_1", ""); _logger.LogInfo("GridMonitoring.ScanForeignPower_2", "** Power **"); _logger.LogInfo("GridMonitoring.ScanForeignPower_3", $"Foreign Battery Count: {MonitoringData.ForeignPowerConsumption.Batteries.Count}"); } private void ScanStorageCapacity(IEnumerable<BlockEntity<IMyTerminalBlock>> withStorageBlocks) { withStorageBlocks .Where(block => block.Exists() && block.IsOfType<IMyCargoContainer>()) .ToList() .ForEach(block => { var inventory = block.Block.GetInventory(); MonitoringData.Cargos.Add(new CargoInfo { Name = block.Block.CustomName, MaxVolume = inventory.MaxVolume, CurrentVolume = inventory.CurrentVolume }); }); _logger.LogInfo("GridMonitoring.ScanStorageCapacity_1", ""); _logger.LogInfo("GridMonitoring.ScanStorageCapacity_2", "** Items **"); _logger.LogInfo("GridMonitoring.ScanStorageCapacity_3", $"Max Storage Capacity: {MonitoringData.Cargos.Sum(x => (float)x.MaxVolume)} m^3"); _logger.LogInfo("GridMonitoring.ScanStorageCapacity_4", $"Current Storage Volume: {MonitoringData.Cargos.Sum(x => (float)x.CurrentVolume)} m^3"); } private void ScanAllInventory(IEnumerable<BlockEntity<IMyTerminalBlock>> blocksWithStorage) { blocksWithStorage .Where(block => block.Exists()) .ToList() .ForEach(block => { var inventoryCount = block.Block.InventoryCount; for (var index = 0; index < inventoryCount; index++) ScanInventory(block.Block.GetInventory(index)); }); var components = MonitoringData.GetItems(Item.ItemTypes.Component); var ingots = MonitoringData.GetItems(Item.ItemTypes.Ingot); var ores = MonitoringData.GetItems(Item.ItemTypes.Ore); var tools = MonitoringData.GetItems(Item.ItemTypes.Tools); var unknowns = MonitoringData.GetItems(Item.ItemTypes.Unknown); _logger.LogInfo("GridMonitoring.ScanAllInventory_1", $"Components found: {components.Count.ToString()}"); _logger.LogInfo("GridMonitoring.ScanAllInventory_2", $"Ingots found: {ingots.Count.ToString()}"); _logger.LogInfo("GridMonitoring.ScanAllInventory_3", $"Ores found: {ores.Count.ToString()}"); _logger.LogInfo("GridMonitoring.ScanAllInventory_4", $"Tools found: {tools.Count.ToString()}"); _logger.LogInfo("GridMonitoring.ScanAllInventory_5", $"Unknowns found: {unknowns.Count.ToString()}"); } private void ScanProduction(IEnumerable<BlockEntity<IMyProductionBlock>> productionBlocks) { productionBlocks .Where(block => block.Exists()) .Select(block => block.Block) .ToList() .ForEach(block => { var items = new List<MyProductionItem>(); block.GetQueue(items); items.ForEach(item => { MonitoringData.AddToQueuedList(item); }); }); var components = MonitoringData.GetItemsInProduction(Item.ItemTypes.Component); var ingots = MonitoringData.GetItemsInProduction(Item.ItemTypes.Ingot); var unknowns = MonitoringData.GetItemsInProduction(Item.ItemTypes.Unknown); _logger.LogInfo("GridMonitoring.ScanProduction_1", $"Components in production found: {components.Count.ToString()}"); _logger.LogInfo("GridMonitoring.ScanProduction_2", $"Ingots in production found: {ingots.Count.ToString()}"); _logger.LogInfo("GridMonitoring.ScanProduction_3", $"Unknown in production found: {unknowns.Count.ToString()}"); } private void ScanInventory(IMyInventory inventory) { var items = new List<MyInventoryItem>(); inventory.GetItems(items); items.ForEach(item => { MonitoringData.AddToInventory(item); }); } } 
 public class HydrogenTankInfo { public string Name { get; set; } public float Capacity { get; set; } public double FilledRatio { get; set; } } 
 public class MonitoringData { private readonly IMyGridAssistantLogger _logger; private Dictionary<MyItemType, Item> _items; private Dictionary<MyDefinitionId, Item> _itemsInProduction; public MonitoringData(IMyGridAssistantLogger logger) { _logger = logger; Reset(); } public PowerInfo PowerConsumption { get; private set; } public PowerInfo ForeignPowerConsumption { get; private set; } public List<CargoInfo> Cargos { get; private set; } public List<HydrogenTankInfo> HydrogenTanks { get; private set; } public void Reset() { _items = new Dictionary<MyItemType, Item>(); _itemsInProduction = new Dictionary<MyDefinitionId, Item>(); PowerConsumption = new PowerInfo(); ForeignPowerConsumption = new PowerInfo(); Cargos = new List<CargoInfo>(); HydrogenTanks = new List<HydrogenTankInfo>(); } public List<Item> GetItemsInProduction() { return _itemsInProduction .Select(c => c.Value) .ToList(); } public List<Item> GetItemsInProduction(Item.ItemTypes type) { return _itemsInProduction .Where(c => c.Value.ItemType == type) .Select(c => c.Value) .ToList(); } public List<Item> GetItems() { return _items .Select(c => c.Value) .ToList(); } public List<Item> GetItems(Item.ItemTypes type) { return _items .Where(c => c.Value.ItemType == type) .Select(c => c.Value) .ToList(); } public void AddToInventory(MyInventoryItem item) { if (_items.ContainsKey(item.Type)) _items[item.Type].Amount += item.Amount.ToIntSafe(); else _items.Add(item.Type, new Item(item.Type, item.Amount.ToIntSafe())); } public void AddToQueuedList(MyProductionItem queuedItem) { if (_itemsInProduction.ContainsKey(queuedItem.BlueprintId)) _itemsInProduction[queuedItem.BlueprintId].Amount += queuedItem.Amount.ToIntSafe(); else _itemsInProduction.Add(queuedItem.BlueprintId, new Item(queuedItem.BlueprintId, queuedItem.Amount.ToIntSafe())); } } 
 public class PowerInfo { public PowerInfo() { Batteries = new List<BatteryInfo>(); Reactors = new List<ReactorInfo>(); SolarPanels = new List<SolarPanelInfo>(); WindTurbines = new List<WindTurbineInfo>(); HydrogenEngines = new List<HydrogenEngineInfo>(); } public List<BatteryInfo> Batteries { get; set; } public List<ReactorInfo> Reactors { get; set; } public List<SolarPanelInfo> SolarPanels { get; set; } public List<WindTurbineInfo> WindTurbines { get; set; } public List<HydrogenEngineInfo> HydrogenEngines { get; set; } public int AvailableUranium { get; set; } public int AvailableIce { get; set; } public float CurrentPowerOutput => Batteries.Sum(b => b.CurrentOutput) + Reactors.Sum(b => b.CurrentOutput) + SolarPanels.Sum(b => b.CurrentOutput) + WindTurbines.Sum(b => b.CurrentOutput) + HydrogenEngines.Sum(b => b.CurrentOutput); public float MaxPowerOutput => Batteries.Sum(b => b.MaxOutput) + Reactors.Sum(b => b.MaxOutput) + SolarPanels.Sum(b => b.MaxOutput) + WindTurbines.Sum(b => b.MaxOutput) + HydrogenEngines.Sum(b => b.MaxOutput); } public class HydrogenEngineInfo { public string Name { get; set; } public float CurrentOutput { get; set; } public float MaxOutput { get; set; } public double FilledRatio { get; set; } } public class WindTurbineInfo { public string Name { get; set; } public float CurrentOutput { get; set; } public float MaxOutput { get; set; } } public class SolarPanelInfo { public string Name { get; set; } public float CurrentOutput { get; set; } public float MaxOutput { get; set; } } public class ReactorInfo { public string Name { get; set; } public float CurrentOutput { get; set; } public float MaxOutput { get; set; } } public class BatteryInfo { public bool IsCharging { get; set; } public float CurrentStoredPower { get; set; } public float MaxStoredPower { get; set; } public string Name { get; set; } public float CurrentOutput { get; set; } public float MaxOutput { get; set; } } 
 public class AutoProducer { private readonly IMyGridAssistantLogger _logger; public AutoProducer(IMyGridAssistantLogger logger) { _logger = logger; } public void Produce( List<Item> allItemsInInventory, List<Item> allItemsInProduction, IEnumerable<Item> itemsToProduce, IEnumerable<BlockEntity<IMyProductionBlock>> blocksProducingItems) { var allowedBlockForProduction = GetAllowedBlocksForProduction(blocksProducingItems); foreach (var itemToProduce in itemsToProduce) { var ownedInventoryCount = allItemsInInventory .Where(ownerItem => ownerItem.IsSameAs(itemToProduce)) .Sum(x => x.Amount); var producingCount = allItemsInProduction .Where(producingItem => producingItem.IsSameAs(itemToProduce)) .Sum(x => x.Amount); var count = ownedInventoryCount + producingCount; if (count >= itemToProduce.Amount) continue; var delta = itemToProduce.Amount - count; if (delta > 0) ProduceItem(itemToProduce, delta, allowedBlockForProduction); } } private List<IMyProductionBlock> GetAllowedBlocksForProduction(IEnumerable<BlockEntity<IMyProductionBlock>> blocks) { return blocks .Where(block => block.Exists()) .Select(block => block.Block) .Where(block => { var isIgnored = Configuration.GetBlockConfiguration(block, Settings.EXCLUDE_FROM_AUTO_PRODUCTION); if (isIgnored != null) { _logger.LogDebug($"block {block.CustomName} ignored for auto producing items", 3); return false; } var assemblerBlock = block as IMyAssembler; if (assemblerBlock == null) return true; if (assemblerBlock.Mode == MyAssemblerMode.Assembly) return true; _logger.LogDebug($"block {block.CustomName} ignored because set in `Disassembly` mode", 3); return false; }) .ToList(); } private void ProduceItem(Item itemToProduce, decimal amount, IReadOnlyCollection<IMyProductionBlock> blocksProducingItems) { var best = GetBestBlockForJob(itemToProduce, blocksProducingItems); if (best == null) { _logger.LogDebug($"No production block found for producing {amount} {itemToProduce.ItemDefinitionId.SubtypeName}"); return; } best.AddQueueItem(itemToProduce.ItemDefinitionId, amount); _logger.LogDebug($"Queued item: {amount} {itemToProduce.ItemDefinitionId.SubtypeName} into {best.CustomName}"); } private static IMyProductionBlock GetBestBlockForJob(Item itemToProduce, IReadOnlyCollection<IMyProductionBlock> blocksProducingItems) { var dict = new Dictionary<long, int>(); if (!blocksProducingItems.Any()) return null; foreach (var block in blocksProducingItems) { if (!block.CanUseBlueprint(itemToProduce.ItemDefinitionId)) continue; var actualQueue = new List<MyProductionItem>(); block.GetQueue(actualQueue); var actualQueueCount = actualQueue.Sum(q => q.Amount.ToIntSafe()); dict.Add(block.EntityId, actualQueueCount); } if (!dict.Any()) return null; var bestBlockId = dict.OrderBy(x => x.Value).First().Key; return blocksProducingItems.First(x => x.EntityId == bestBlockId); } } 
